function applyLanguage(lang){const t=copy[lang]||copy.ko;document.documentElement.lang=lang;document.querySelector('nav a').textContent=t.nav;const labels={all:t.all,major:t.major,korea:t.korea,asia:t.asia,japan:t.japan,china:t.china,striking:t.striking};document.querySelectorAll('.filter').forEach(button=>{if(labels[button.dataset.filter])button.textContent=labels[button.dataset.filter]});document.querySelector('.timezone-note').textContent=t.note;document.querySelector('.subscribe b').textContent=t.subscribe;language.value=lang;localStorage.setItem('mma-calendar-language',lang)}
