function renderDetail(){const f=active.fights||[],p=mapPins[active.city]||[50,50],pairs=[];for(let i=0;i<f.length;i+=2)pairs.push([f[i],f[i+1]||['TBA','—']]);const ordered=pairs,links=[active.officialUrl&&`<a href="${active.officialUrl}" target="_blank" rel="noopener">공식 홈페이지</a>`,active.instagramUrl&&`<a href="${active.instagramUrl}" target="_blank" rel="noopener">Instagram</a>`,active.watchUrl&&`<a href="${active.watchUrl}" target="_blank" rel="noopener">티켓 / PPV</a>`].filter(Boolean).join('');detail.innerHTML=`<div class="detail-tag">${active.p} · ${active.cat==='major'?'MAJOR PROMOTION':'EVENT'}</div><h2>${active.n}</h2><div class="detail-date">${active.kst} · ${active.city}</div><div class="info"><div><b>현지 시작</b>${active.zone}</div><div><b>한국 시간</b>${active.kst}</div><div><b>개최 장소</b>${active.venue}</div><div><b>시청</b>${active.watch}</div></div><div class="map world-map"><div class="map-grid"></div><i class="pin" style="left:${p[0]}%;top:${p[1]}%"></i><span class="map-label">${active.city}</span></div><h3 class="card-heading">FIGHT ORDER <small>· 공식 카드 순서</small></h3>${ordered.length?ordered.map((pair,i)=>`<div class="fight"><i class="fighter-pic"></i><div>${pair[0][0]}<span>${pair[0][1]}</span></div><strong>${i===0?'MAIN':i===1?'CO-MAIN':i-1}<br>VS</strong><div style="text-align:right">${pair[1][0]}<span>${pair[1][1]}</span></div></div>`).join(''):'<p class="fight-status">공식 대진 미발표</p>'}${links?`<div class="links">${links}</div>`:''}`}
