async function loadOfficialSchedule(){try{const response=await fetch('/api/events?promotion=ufc');if(!response.ok)return;const payload=await response.json();if(!Array.isArray(payload.events)||!payload.events.length)return;const refreshed=payload.events.map(item=>{const current=events.find(event=>event.p==='UFC'&&event.officialUrl===item.officialUrl);return current?{...current,sourceFetchedAt:item.fetchedAt,posterUrl:item.posterUrl||current.posterUrl,posterType:item.posterType||current.posterType,posterSourceUrl:item.posterSourceUrl||current.posterSourceUrl}:null}).filter(Boolean);const additions=payload.events.filter(item=>item.startsAt&&!events.some(event=>event.officialUrl===item.officialUrl)).map(item=>{const at=new Date(item.startsAt);const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(at).replaceAll('/','-');const kst=new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(at).replace(',','');return {date,p:'UFC',n:item.title.replace(/^UFC\s*/,''),city:item.city||'공식 개최지 확인 중',zone:'현지 시각 · 공식 페이지 기준',kst:`${kst} KST`,cat:'major',venue:item.venue||'공식 장소 확인 중',watch:'Paramount+ · UFC Fight Pass',officialUrl:item.officialUrl,instagramUrl:'https://www.instagram.com/ufc/',watchUrl:'https://www.ufc.com/watch/schedule',posterUrl:item.posterUrl,posterType:item.posterType,posterSourceUrl:item.posterSourceUrl,posterStatus:item.posterStatus,fights:[]}});if(refreshed.length||additions.length){events=[...events.map(event=>refreshed.find(item=>item.officialUrl===event.officialUrl)||event),...additions];renderDays();renderDetail()}}catch{ /* Static fallback remains usable while the official adapter is temporarily unavailable. */ }}
async function loadRoadSchedule(){try{const response=await fetch('/api/events?promotion=road-fc');if(!response.ok)return;const payload=await response.json();if(!Array.isArray(payload.events)||!payload.events.length)return;const incoming=payload.events.map(item=>{const current=events.find(event=>event.p==='ROAD FC'&&event.n.includes(item.number));return current?{...current,sourceFetchedAt:item.fetchedAt,officialUrl:item.officialUrl,posterUrl:null,posterType:null,posterSourceUrl:null}:{date:item.date,p:'ROAD FC',n:item.title,city:item.city,zone:'KST (UTC+9)',kst:`${Number(item.date.slice(5,7))}월 ${Number(item.date.slice(8,10))}일 · 공식 시작 시각 미발표`,cat:'korea',categories:['korea'],venue:item.venue,watch:'ROAD FC 공식 채널',officialUrl:item.officialUrl,instagramUrl:item.instagramUrl,posterUrl:null,posterType:null,posterSourceUrl:null,fights:[]}});events=[...events.filter(event=>!incoming.some(item=>item.p==='ROAD FC'&&event.n.includes(item.n.split(' ').pop()))),...incoming];renderDays();renderDetail()}catch{ /* Static fallback remains usable while the official adapter is temporarily unavailable. */ }}
async function loadBlackCombatSchedule(){try{const response=await fetch('/api/events?promotion=black-combat');if(!response.ok)return;const payload=await response.json();if(!Array.isArray(payload.events)||!payload.events.length)return;const incoming=payload.events.map(item=>{const current=events.find(event=>event.p==='BLACK COMBAT'&&event.date===item.date);const official={officialUrl:item.officialUrl,sourceFetchedAt:item.fetchedAt,posterUrl:item.posterUrl,posterType:item.posterType,posterSourceUrl:item.posterSourceUrl};return current?{...current,...official,n:item.title||current.n,venue:item.venue||current.venue}:{date:item.date,p:'BLACK COMBAT',n:item.title||'BLACK COMBAT',city:item.city||'Korea',zone:'KST (UTC+9)',kst:`${Number(item.date.slice(5,7))}월 ${Number(item.date.slice(8,10))}일 · 공식 시작 시각 미발표`,cat:'korea',categories:['korea'],venue:item.venue||'공식 장소 확인 중',watch:'BLACK COMBAT 공식 채널',instagramUrl:'https://www.instagram.com/blackcombat_official/',...official,fights:[]}});events=[...events.map(event=>incoming.find(item=>item.p==='BLACK COMBAT'&&item.date===event.date)||event),...incoming.filter(item=>!events.some(event=>event.p==='BLACK COMBAT'&&event.date===item.date))];renderDays();renderDetail()}catch{}}
async function loadPancraseSchedule(){try{const response=await fetch('/api/events?promotion=pancrase');if(!response.ok)return;const payload=await response.json();if(!Array.isArray(payload.events)||!payload.events.length)return;const used=new Set(),replacements=new Map(),additions=[];payload.events.forEach(item=>{const index=events.findIndex((event,i)=>!used.has(i)&&event.p==='PANCRASE'&&event.date===item.date);const official={officialUrl:item.officialUrl,posterUrl:item.posterUrl,posterType:item.posterType,posterSourceUrl:item.posterSourceUrl,sourceFetchedAt:item.fetchedAt};if(index>=0){used.add(index);replacements.set(index,{...events[index],...official,n:item.title||events[index].n})}else additions.push({date:item.date,p:'PANCRASE',n:item.title,city:'Japan',zone:'JST (UTC+9)',kst:`${Number(item.date.slice(5,7))}월 ${Number(item.date.slice(8,10))}일 · 공식 시작 시각 미발표`,cat:'japan',categories:['japan','fightpass'],venue:'공식 장소 확인 중',watch:'U-NEXT · UFC Fight Pass',watchUrl:'https://ufcfightpass.com/',instagramUrl:'https://www.instagram.com/_pancrase_/',...official,fights:[]})});events=[...events.map((event,index)=>replacements.get(index)||event),...additions];renderDays();renderDetail()}catch{}}
async function loadDeepSchedule(){try{const response=await fetch('/api/events?promotion=deep');if(!response.ok)return;const payload=await response.json();if(!Array.isArray(payload.events)||!payload.events.length)return;const used=new Set(),replacements=new Map(),additions=[];payload.events.forEach(item=>{const existingIndex=events.findIndex((event,index)=>!used.has(index)&&event.p===item.promotion&&event.date===item.date);const official={officialUrl:item.officialUrl,posterUrl:item.posterUrl,posterType:item.posterType,posterSourceUrl:item.posterSourceUrl,sourceFetchedAt:item.fetchedAt};if(existingIndex>=0){used.add(existingIndex);replacements.set(existingIndex,{...events[existingIndex],...official,n:item.title||events[existingIndex].n})}else additions.push({date:item.date,p:item.promotion,n:item.title,city:item.city,zone:'JST (UTC+9)',kst:`${Number(item.date.slice(5,7))}월 ${Number(item.date.slice(8,10))}일 · 공식 시작 시각 미발표`,cat:'japan',categories:['japan'],venue:'공식 장소 확인 중',watch:'DEEP 공식 채널',...official,fights:[]})});events=[...events.map((event,index)=>replacements.get(index)||event),...additions];renderDays();renderDetail()}catch{}}
async function loadOneSchedule(){try{const response=await fetch('/api/events?promotion=one');if(!response.ok)return;const payload=await response.json();if(!Array.isArray(payload.events)||!payload.events.length)return;const incoming=payload.events.map(item=>({date:item.date,p:'ONE',n:item.title,city:item.city||'공식 개최지 확인 중',zone:item.title.includes('SAMURAI')?'JST (UTC+9)':'공식 현지 시각',kst:`${Number(item.date.slice(5,7))}월 ${Number(item.date.slice(8,10))}일 · 공식 시작 시각 확인 중`,cat:'major',categories:item.title.includes('SAMURAI')?['major','japan']:['major'],venue:item.venue||'공식 장소 확인 중',watch:'watch.onefc.com',officialUrl:item.officialUrl,posterUrl:item.posterUrl,posterType:item.posterType,posterSourceUrl:item.posterSourceUrl,sourceFetchedAt:item.fetchedAt,fights:[]}));events=[...events.filter(event=>!incoming.some(item=>item.officialUrl===event.officialUrl||item.p===event.p&&item.date===event.date&&item.n===event.n)),...incoming];renderDays();renderDetail()}catch{}}
async function loadZfnSchedule(){try{const response=await fetch('/api/events?promotion=zfn');if(!response.ok)return;const payload=await response.json();if(!Array.isArray(payload.events)||!payload.events.length)return;const incoming=payload.events.map(item=>({date:item.date,p:'ZFN',n:item.title,city:item.city,zone:'KST (UTC+9)',kst:`${Number(item.date.slice(5,7))}월 ${Number(item.date.slice(8,10))}일 · 공식 시작 시각 확인 중`,cat:'korea',categories:['korea','fightpass'],venue:item.venue,watch:'UFC Fight Pass',watchUrl:'https://ufcfightpass.com/',officialUrl:item.officialUrl,instagramUrl:item.instagramUrl,posterUrl:item.posterUrl,posterType:item.posterType,posterSourceUrl:item.posterSourceUrl,sourceFetchedAt:item.fetchedAt,fights:[]}));events=[...events.filter(event=>!incoming.some(item=>item.p===event.p&&item.date===event.date)),...incoming];renderDays();renderDetail()}catch{}}
const rizinEventKey=value=>(value||'').replaceAll(/[^A-Za-z0-9\u3040-\u30ff\u3400-\u9fff]/g,'').toLowerCase();
const sameRizinEvent=(left,right)=>left.p==='RIZIN'&&(left.date===right.date||rizinEventKey(left.n).includes(rizinEventKey(right.n))||rizinEventKey(right.n).includes(rizinEventKey(left.n)));
async function loadRizinSchedule(){try{const response=await fetch('/api/events?promotion=rizin');if(!response.ok)return;const payload=await response.json();if(!Array.isArray(payload.events)||!payload.events.length)return;const incoming=payload.events.map(item=>{const probe={p:'RIZIN',date:item.date,n:item.title};const current=events.find(event=>sameRizinEvent(event,probe));const time=item.startsAtLocal?`${Number(item.date.slice(5,7))}월 ${Number(item.date.slice(8,10))}일 ${item.startsAtLocal} KST`:`${Number(item.date.slice(5,7))}월 ${Number(item.date.slice(8,10))}일 · 공식 시작 시각 미발표`;const official={sourceFetchedAt:item.fetchedAt,officialUrl:item.officialUrl,posterUrl:item.posterUrl,posterType:item.posterType,posterSourceUrl:item.posterSourceUrl,posterStatus:item.posterStatus};return current?{...current,...official,kst:item.startsAtLocal?time:current.kst,venue:item.venue||current.venue}:{date:item.date,p:'RIZIN',n:item.title,city:'Japan',zone:'JST (UTC+9)',kst:time,cat:'japan',categories:['japan','major'],venue:item.venue||'공식 장소 확인 중',watch:'RIZIN.tv · U-NEXT',officialUrl:item.officialUrl,instagramUrl:'https://www.instagram.com/rizin_pr/',...official,fights:[]}});events=[...events.map(event=>{const matched=incoming.find(item=>sameRizinEvent(event,item));return matched||event}),...incoming.filter(item=>!events.some(event=>sameRizinEvent(event,item)))];renderDays();renderDetail()}catch{ /* Static fallback remains usable while the official adapter is temporarily unavailable. */ }}
async function loadFightPassSchedule(){try{const response=await fetch('/api/fightpass');if(!response.ok)return;const payload=await response.json();if(!Array.isArray(payload.events)||!payload.events.length)return;const incoming=payload.events.map(item=>({date:item.date,p:item.promotion,n:item.title,city:'공식 개최지 확인 중',zone:'현지 시각 · UFC Fight Pass 공식 일정 기준',kst:`${Number(item.date.slice(5,7))}월 ${Number(item.date.slice(8,10))}일 ${item.kstTime} KST`,cat:'fightpass',categories:item.categories,venue:'공식 장소 확인 중',watch:'UFC Fight Pass',officialUrl:item.officialUrl,watchUrl:item.watchUrl,sourceFetchedAt:item.fetchedAt,fights:[]}));events=[...events.filter(event=>!incoming.some(item=>item.officialUrl===event.officialUrl)),...incoming];renderDays();renderDetail()}catch{ /* Existing official entries remain visible while the Fight Pass schedule is unavailable. */ }}
renderDays();renderDetail();loadOfficialSchedule();
loadRoadSchedule();
